from collections import defaultdict

def build_adj_list(edges):
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)  # undirected
    return adj_list

def dfs(adjList):
    visited = set()
    def dfs_helper(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in adjList[node]:
            dfs_helper(neighbor)
    for node in adjList:
        if node not in visited:
            dfs_helper(node)
